def evaluate(tokens):
    stack=[]
    for token in tokens:
        if token not in ['+','-','*']:stack.append(int(token));continue
        if len(stack)<2:raise ValueError('Missing operands')
        b=stack.pop();a=stack.pop()
        stack.append(a+b if token=='+' else a-b if token=='-' else a*b)
    if len(stack)!=1:raise ValueError('Invalid expression')
    return stack[0]
